   public static DeferredItem<Item> block(DeferredHolder<Block, Block> block, Properties props) {
      return REGISTRY.registerItem(block.getId().getPath(), prop -> new BlockItem((Block)block.get(), prop), props);
   }

   public static DeferredItem<Item> blockItem(DeferredHolder<Block, Block> block, Properties props) {
      return REGISTRY.registerItem(block.getId().getPath(), prop -> new BlockItem((Block)block.get(), prop), props);
   }

   private static <I extends Item> DeferredItem<I> registerCompostable(String name, Function<Properties, ? extends I> supplier) {
      return REGISTRY.registerItem(name, supplier, new Properties().component(DataComponents.COMPOSTABLE, new Compostable(new Constant(30))));
   }

   private static <I extends Item> DeferredItem<I> register(String name, Function<Properties, ? extends I> supplier) {
      return REGISTRY.registerItem(name, supplier, new Properties());
   }
